package raft

import("errors";"sync";"testing";"time")
type memNet struct{mu sync.Mutex;nodes map[string]*Node;down map[string]bool}
type memTransport struct{net *memNet;self string}
func(t *memTransport)Call(peer,method string,args,reply any)error{t.net.mu.Lock();target:=t.net.nodes[peer];cut:=t.net.down[peer]||t.net.down[t.self];t.net.mu.Unlock();if target==nil||cut{return errors.New("unreachable")};switch method{case "RequestVote":*reply.(*RequestVoteReply)=target.HandleRequestVote(args.(*RequestVoteArgs));case "AppendEntries":*reply.(*AppendEntriesReply)=target.HandleAppendEntries(args.(*AppendEntriesArgs))};return nil}
type testCluster struct{net *memNet;ids []string;mu sync.Mutex;applied map[string][]string}
func newTestCluster(t *testing.T,ids ...string)*testCluster{c:=&testCluster{net:&memNet{nodes:map[string]*Node{},down:map[string]bool{}},ids:ids,applied:map[string][]string{}};for _,id:=range ids{id:=id;var peers []string;for _,p:=range ids{if p!=id{peers=append(peers,p)}};n,e:=New(Config{ID:id,Peers:peers,Transport:&memTransport{net:c.net,self:id},ElectionMin:80*time.Millisecond,ElectionMax:160*time.Millisecond,Heartbeat:20*time.Millisecond,Apply:func(_ uint64,cmd []byte)any{c.mu.Lock();c.applied[id]=append(c.applied[id],string(cmd));c.mu.Unlock();return nil}});if e!=nil{t.Fatal(e)};c.net.mu.Lock();c.net.nodes[id]=n;c.net.mu.Unlock()};t.Cleanup(func(){for _,n:=range c.net.nodes{n.Stop()}});return c}
func(c *testCluster)leader(t *testing.T,exclude string)*Node{t.Helper();deadline:=time.Now().Add(5*time.Second);for time.Now().Before(deadline){for _,id:=range c.ids{if id==exclude{continue};n:=c.net.nodes[id];c.net.mu.Lock();down:=c.net.down[id];c.net.mu.Unlock();if !down&&n.Status().Role=="leader"{return n}};time.Sleep(10*time.Millisecond)};t.Fatal("no leader elected");return nil}
func(c *testCluster)waitApplied(t *testing.T,id string,want []string){t.Helper();deadline:=time.Now().Add(5*time.Second);for time.Now().Before(deadline){c.mu.Lock();got:=append([]string(nil),c.applied[id]...);c.mu.Unlock();if len(got)==len(want){ok:=true;for i:=range got{if got[i]!=want[i]{ok=false}};if ok{return}};time.Sleep(10*time.Millisecond)};c.mu.Lock();defer c.mu.Unlock();t.Fatalf("node %s applied %v want %v",id,c.applied[id],want)}
func TestElectsSingleLeader(t *testing.T){c:=newTestCluster(t,"a","b","c");c.leader(t,"");time.Sleep(300*time.Millisecond);leaders:=0;for _,id:=range c.ids{if c.net.nodes[id].Status().Role=="leader"{leaders++}};if leaders!=1{t.Fatalf("want exactly one leader, got %d",leaders)}}
func TestReplicatesAndApplies(t *testing.T){c:=newTestCluster(t,"a","b","c");l:=c.leader(t,"");want:=[]string{"one","two","three"};for _,cmd:=range want{if _,e:=l.Propose([]byte(cmd),3*time.Second);e!=nil{t.Fatal(e)}};for _,id:=range c.ids{c.waitApplied(t,id,want)}}
func TestLeaderFailoverKeepsCommittedData(t *testing.T){c:=newTestCluster(t,"a","b","c");old:=c.leader(t,"");oldID:=old.Status().ID;if _,e:=old.Propose([]byte("x"),3*time.Second);e!=nil{t.Fatal(e)};c.net.mu.Lock();c.net.down[oldID]=true;c.net.mu.Unlock();next:=c.leader(t,oldID);if _,e:=next.Propose([]byte("y"),3*time.Second);e!=nil{t.Fatal(e)};if _,e:=old.Propose([]byte("lost"),400*time.Millisecond);e==nil{t.Fatal("isolated leader committed without majority")};c.net.mu.Lock();c.net.down[oldID]=false;c.net.mu.Unlock();for _,id:=range c.ids{c.waitApplied(t,id,[]string{"x","y"})}}
